CREATE TABLE actors(id uuid PRIMARY KEY, external_id text UNIQUE NOT NULL CHECK(external_id ~ '^[1-9][0-9]{0,18}$' AND external_id::numeric<=9223372036854775807), display_name text NOT NULL);
CREATE TABLE plans(id uuid PRIMARY KEY, organizer_id uuid NOT NULL REFERENCES actors(id),state_version integer NOT NULL CHECK(state_version>0),state jsonb NOT NULL CHECK(state->>'version'='max.backend.23.v1-candidate' AND (state->>'stateVersion')::integer=state_version));
CREATE TABLE plan_slots(plan_id uuid NOT NULL REFERENCES plans(id),slot_id uuid NOT NULL,actor_id uuid REFERENCES actors(id),state text NOT NULL CHECK(state IN ('UNBOUND','ACTIVE','LEFT')),PRIMARY KEY(plan_id,slot_id),CHECK(state<>'ACTIVE' OR actor_id IS NOT NULL),CHECK(state<>'UNBOUND' OR actor_id IS NULL));
CREATE UNIQUE INDEX one_active_slot_per_actor ON plan_slots(plan_id,actor_id) WHERE state='ACTIVE';
CREATE TABLE snapshots(id uuid PRIMARY KEY,plan_id uuid NOT NULL REFERENCES plans(id),option_id uuid NOT NULL,body jsonb NOT NULL);
CREATE TABLE command_receipts(scope text NOT NULL,actor_id uuid NOT NULL REFERENCES actors(id),key uuid NOT NULL,payload_hash text NOT NULL,body jsonb NOT NULL,PRIMARY KEY(scope,actor_id,key));
CREATE TABLE command_audit(id uuid PRIMARY KEY,plan_id uuid NOT NULL REFERENCES plans(id),actor_id uuid NOT NULL REFERENCES actors(id),kind text NOT NULL,state_version integer NOT NULL,request_id text NOT NULL,accepted_at timestamptz NOT NULL);
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'immutable audit row'; END;$$;
CREATE TRIGGER immutable_snapshot BEFORE UPDATE OR DELETE ON snapshots FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_command BEFORE UPDATE OR DELETE ON command_audit FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE invites(id uuid PRIMARY KEY,plan_id uuid NOT NULL REFERENCES plans(id),token_hash text UNIQUE NOT NULL,create_key uuid NOT NULL,expected_revision integer NOT NULL,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,UNIQUE(plan_id,create_key));
CREATE TABLE join_requests(plan_id uuid NOT NULL REFERENCES plans(id),actor_id uuid NOT NULL REFERENCES actors(id),state text NOT NULL CHECK(state IN ('PENDING','APPROVED','REJECTED','REMOVED')),PRIMARY KEY(plan_id,actor_id));
CREATE TABLE session_bootstraps(id uuid PRIMARY KEY,binding_hash text UNIQUE NOT NULL,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE app_sessions(id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES actors(id),family_id uuid NOT NULL,token_hash text UNIQUE NOT NULL,issued_at timestamptz NOT NULL,absolute_expires_at timestamptz NOT NULL,last_seen_at timestamptz NOT NULL,csrf_generation integer NOT NULL DEFAULT 1,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE session_exchanges(binding_hash text UNIQUE NOT NULL,exchange_key uuid NOT NULL,proof_hash text UNIQUE NOT NULL,session_id uuid NOT NULL REFERENCES app_sessions(id),escrow text,escrow_expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,PRIMARY KEY(binding_hash,exchange_key));
CREATE TABLE destinations(actor_id uuid PRIMARY KEY REFERENCES actors(id),chat_id text NOT NULL CHECK(chat_id ~ '^-?[0-9]{1,19}$'),verified_at timestamptz NOT NULL,source_digest text NOT NULL);
CREATE TABLE inbox(id uuid PRIMARY KEY,event_key text UNIQUE NOT NULL,payload_hash text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT clock_timestamp(),kind text NOT NULL,processed boolean NOT NULL DEFAULT false);
CREATE TABLE quarantine(id uuid PRIMARY KEY,payload_hash text NOT NULL,reason text NOT NULL,raw_cipher text,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE max_ingress_owner(credential_scope text PRIMARY KEY,mode text NOT NULL CHECK(mode IN ('WEBHOOK','POLLING')),marker text);
CREATE TABLE outbound_control(id integer PRIMARY KEY CHECK(id=1),hold boolean NOT NULL DEFAULT true,reason text NOT NULL,epoch text NOT NULL);
INSERT INTO outbound_control VALUES(1,true,'INITIAL_HOLD','UNINITIALIZED');
CREATE TABLE outbox(id uuid PRIMARY KEY,command_id uuid NOT NULL REFERENCES command_audit(id),plan_id uuid NOT NULL REFERENCES plans(id),actor_id uuid NOT NULL REFERENCES actors(id),kind text NOT NULL CHECK(kind='PLAN_NOTICE'),state text NOT NULL CHECK(state IN ('READY','QUEUED','RUNNING','SUCCEEDED','RETRY_WAIT','UNKNOWN','DEAD','CANCELLED','EXPIRED')),attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count>=0),not_before timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,lease_until timestamptz,lease_owner uuid,queue_generation integer NOT NULL DEFAULT 0,queued_at timestamptz,result_reason text,provider_mid text,UNIQUE(command_id,actor_id,kind));
CREATE INDEX outbox_reconcile ON outbox(state,not_before);
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY,outbox_id uuid NOT NULL REFERENCES outbox(id),lease_owner uuid NOT NULL,started_at timestamptz NOT NULL DEFAULT clock_timestamp(),wire_started_at timestamptz,outcome text,finished_at timestamptz,reason text,UNIQUE(outbox_id,lease_owner));
CREATE TABLE test_transport_receipts(attempt_id uuid PRIMARY KEY REFERENCES delivery_attempts(id),outbox_id uuid NOT NULL REFERENCES outbox(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
